insert into public.towns (slug,name,image,intro,nearest_lakes,known_for,nearest_large_town,nearby)
values
('minocqua', 'Minocqua', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1800&q=88', 'Known as the Island City, Minocqua sits at the heart of a chain of lakes with an easygoing downtown made for wandering. Spend the morning on the water, then settle in for a sunset supper club dinner.', 'Minocqua Chain, Lake Tomahawk, Kawaguesaga Lake', 'Island City, boating, family weekends', 'Rhinelander', ARRAY['woodruff', 'eagle-river', 'manitowish-waters'])
('eagle-river', 'Eagle River', 'https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=1800&q=88', 'Eagle River is the snowmobile trail capital of the world and home to the famous Chain of 28 Lakes. It is the kind of place where a day on the trail turns into a dockside drink without much planning.', 'Chain of 28 Lakes, Cranberry Lake, Yellow Birch Lake', 'Snowmobiling, boating, family traditions', 'Rhinelander', ARRAY['minocqua', 'land-o-lakes', 'conover'])
('boulder-junction', 'Boulder Junction', 'https://images.unsplash.com/photo-1497250681960-ef046c08a56e?auto=format&fit=crop&w=1800&q=88', 'Boulder Junction wears its Musky Capital of the World reputation proudly, but the real draw is its calm, clear-water rhythm. Bike the Heart of the Forest, paddle quiet lakes, and leave room for a bakery stop.', 'Trout Lake, Boulder Lake, High Lake', 'Muskies, cycling, clear lakes', 'Minocqua', ARRAY['presque-isle', 'manitowish-waters', 'minocqua'])
('presque-isle', 'Presque Isle', 'https://images.unsplash.com/photo-1531497865144-0464ef8fb9a9?auto=format&fit=crop&w=1800&q=88', 'With dark skies, quiet roads, and a pair of remarkably clear lakes, Presque Isle feels a little removed from the everyday. Come for the stars and stay for the slow mornings on the water.', 'Lac Vieux Desert, Presque Isle Lake, Crab Lake', 'Dark skies, clear lakes, quiet trails', 'Boulder Junction', ARRAY['boulder-junction', 'manitowish-waters', 'land-o-lakes'])
('manitowish-waters', 'Manitowish Waters', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1800&q=88', 'Manitowish Waters is a collection of lakes, islands, and small moments that reward a slower pace. Paddle through the Manitowish River, explore local art, and let the woods do the rest.', 'Manitowish Chain, Spider Lake, Rest Lake', 'Paddling, art, quiet lake country', 'Minocqua', ARRAY['presque-isle', 'boulder-junction', 'minocqua'])
('land-o-lakes', 'Land O’ Lakes', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=1800&q=88', 'Land O’ Lakes sits right on the border and deep in the woods, with a long list of lakes and a welcoming small-town center. It is a favorite launch point for paddlers, anglers, and snowmobile riders.', 'Lac Vieux Desert, Gateway Lake, Big Lake', 'Fishing, paddling, borderland trails', 'Eagle River', ARRAY['eagle-river', 'presque-isle', 'mercer'])
('rhinelander', 'Rhinelander', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1800&q=88', 'Rhinelander is the Northwoods’ friendly hub: part working town, part outdoor basecamp, and home to the legendary Hodag. Find local makers downtown, then follow the trails and lakes just beyond town.', 'Boom Lake, Crescent Lake, Lake Thompson', 'Hodag lore, local makers, trail access', 'Wausau', ARRAY['minocqua', 'mercer', 'eagle-river'])
('mercer', 'Mercer', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1800&q=88', 'Mercer is a relaxed gateway to the Turtle-Flambeau Scenic Waters Area, where paddling routes and quiet campsites stretch farther than the map suggests. The town keeps things simple, warm, and wonderfully outdoorsy.', 'Turtle-Flambeau Flowage, Lake of the Falls, Mercer Lake', 'Paddling, camping, fall color', 'Ironwood', ARRAY['land-o-lakes', 'rhinelander', 'hurley-ironwood'])
('hurley-ironwood', 'Hurley / Ironwood', 'https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=1800&q=88', 'Across the Wisconsin–Michigan border, Hurley and Ironwood make one big, colorful basecamp for western U.P. adventures. Ski hills, waterfalls, snowmobile routes, and a lively main street are all close at hand.', 'Montreal River, Lake Gogebic, Turtle-Flambeau Flowage', 'Waterfalls, winter sports, borderland culture', 'Ashland', ARRAY['mercer', 'rhinelander', 'land-o-lakes'])
insert into public.listings (id,slug,name,category,subtype,town,price_range,tags,description,images,is_featured,is_enhanced,phone,website,address)
values
('stay-01', 'pine-shadow-cabins', 'Pine Shadow Cabins', 'stay', 'cabin', 'minocqua', '$$', ARRAY['Dock', 'Pet Friendly', 'Waterfront'], 'A handful of quiet, lakefront cabins tucked among pines on the Minocqua chain.', ARRAY['https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1449158743715-0a90ebb6d2d8?auto=format&fit=crop&w=1000&q=85'], true, false, '(715) 555-0142', 'https://example.com', '812 Pine Shadow Road, Minocqua, WI')
('stay-02', 'wildwood-resort-eagle-river', 'Wildwood Resort', 'stay', 'resort', 'eagle-river', '$$$', ARRAY['Boat Launch', 'Families', 'Fireplace'], 'Classic Eagle River resort cabins with a sandy beach, boat rentals, and a very good sunset.', ARRAY['https://images.unsplash.com/photo-1449158743715-0a90ebb6d2d8?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=1000&q=85'], true, false, '(715) 555-0188', NULL, '1100 Chain Lake Road, Eagle River, WI')
('stay-03', 'boulder-bear-lodge', 'Boulder Bear Lodge', 'stay', 'cabin', 'boulder-junction', '$$', ARRAY['Sauna', 'Lake Access', 'Quiet'], 'A modern-rustic lodge near clear water and the Heart of the Forest bike trail.', ARRAY['https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1497250681960-ef046c08a56e?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1000&q=85'], false, true, '(715) 555-0137', NULL, '2840 County Road K, Boulder Junction, WI')
('stay-04', 'dark-sky-lake-house', 'Dark Sky Lake House', 'stay', 'vacation-rental', 'presque-isle', '$$$', ARRAY['Dark Sky', 'Dock', 'Sleeps 8'], 'A spacious lake house for stargazers, swimmers, and long dinners on the deck.', ARRAY['https://images.unsplash.com/photo-1531497865144-0464ef8fb9a9?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1000&q=85'], false, true, '(715) 555-0164', NULL, '19 Clear Sky Lane, Presque Isle, WI')
('stay-05', 'manitowish-waters-inn', 'Manitowish Waters Inn', 'stay', 'hotel', 'manitowish-waters', '$$', ARRAY['Breakfast', 'Paddles', 'River Access'], 'A warm, welcoming inn with easy access to the river, town, and a dozen good paddles.', ARRAY['https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1449158743715-0a90ebb6d2d8?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=1000&q=85'], false, false, '(715) 555-0171', NULL, '740 County Highway W, Manitowish Waters, WI')
('stay-06', 'gateway-campground', 'Gateway Campground', 'stay', 'campground', 'land-o-lakes', '$', ARRAY['RV Sites', 'Showers', 'Trails'], 'Simple, shaded campsites a short ride from the lakes and borderland trail network.', ARRAY['https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1000&q=85'], false, false, '(715) 555-0191', NULL, '1660 State Highway 45, Land O’ Lakes, WI')
('stay-07', 'hodag-hotel', 'The Hodag Hotel', 'stay', 'hotel', 'rhinelander', '$$', ARRAY['Downtown', 'Coffee', 'Pet Friendly'], 'A tidy downtown base for makers, trail riders, and anyone curious about the Hodag.', ARRAY['https://images.unsplash.com/photo-1449158743715-0a90ebb6d2d8?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1514924013411-cbf25faa35bb?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=1000&q=85'], false, false, '(715) 555-0118', NULL, '26 Brown Street, Rhinelander, WI')
('stay-08', 'turtle-flambeau-outpost', 'Turtle-Flambeau Outpost', 'stay', 'cabin', 'mercer', '$$', ARRAY['Boat Landing', 'Campfire', 'Secluded'], 'Off-grid feeling without giving up a comfortable bed, a fire ring, or easy water access.', ARRAY['https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1000&q=85'], false, false, '(715) 555-0126', NULL, 'Wilderness Road, Mercer, WI')
('stay-09', 'montreal-river-lodge', 'Montreal River Lodge', 'stay', 'resort', 'hurley-ironwood', '$$', ARRAY['Ski Access', 'Trailside', 'Sauna'], 'A trail-friendly lodge for waterfall chasers, ski days, and big breakfasts.', ARRAY['https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1449158743715-0a90ebb6d2d8?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1000&q=85'], false, true, '(715) 555-0169', NULL, '503 Silver Street, Hurley, WI')
('stay-10', 'northwoods-bunkhouse', 'Northwoods Bunkhouse', 'stay', 'B&B', 'eagle-river', '$$', ARRAY['Breakfast', 'Bikes', 'Local Hosts'], 'A friendly, unfussy stay near the chain with a porch made for morning coffee.', ARRAY['https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1000&q=85'], false, false, '(715) 555-0107', NULL, '15 Mill Street, Eagle River, WI')
('eat-01', 'the-boathouse-minocqua', 'The Boathouse', 'eat-drink', 'restaurant', 'minocqua', '$$', ARRAY['Waterfront', 'Patio', 'Fish Fry'], 'Lakeside plates, cold drinks, and a front-row seat to a Minocqua sunset.', ARRAY['https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=1000&q=85'], true, false, '(715) 555-0122', 'https://example.com', '201 Lakeshore Drive, Minocqua, WI')
('eat-02', 'northfork-supper-club', 'Northfork Supper Club', 'eat-drink', 'supper club', 'eagle-river', '$$$', ARRAY['Prime Rib', 'Old Fashioned', 'Reservations'], 'A proper Northwoods supper club with generous pours and an even better Friday fish fry.', ARRAY['https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1000&q=85'], true, false, '(715) 555-0156', NULL, '407 County Road G, Eagle River, WI')
('eat-03', 'boulder-bakery', 'Boulder Bakery', 'eat-drink', 'coffee', 'boulder-junction', '$', ARRAY['Pastries', 'Coffee', 'Local Favorite'], 'Warm pastries, strong coffee, and the kind of morning stop that becomes a tradition.', ARRAY['https://images.unsplash.com/photo-1509440159596-0249088772ff?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1000&q=85'], false, true, '(715) 555-0147', NULL, '105 Main Street, Boulder Junction, WI')
('eat-04', 'clearwater-tap', 'Clearwater Tap & Grill', 'eat-drink', 'bar', 'presque-isle', '$$', ARRAY['Burgers', 'Live Music', 'Dockside'], 'A cheerful lake-country bar with burgers, live music, and a dockside table when the weather cooperates.', ARRAY['https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1000&q=85'], false, false, '(715) 555-0159', NULL, '11 County Highway P, Presque Isle, WI')
('eat-05', 'manitowish-brewing', 'Manitowish Brewing Co.', 'eat-drink', 'brewery', 'manitowish-waters', '$$', ARRAY['Taps', 'Pretzels', 'Dog Friendly'], 'Small-batch beer, river-town conversation, and a sunny patio made for the end of the paddle.', ARRAY['https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1000&q=85'], false, true, '(715) 555-0112', NULL, '28 Hwy 51, Manitowish Waters, WI')
('eat-06', 'the-pioneer-bar', 'The Pioneer Bar', 'eat-drink', 'supper club', 'land-o-lakes', '$$', ARRAY['Fish Fry', 'Darts', 'Local Favorite'], 'A beloved Land O’ Lakes stop for Friday fish, a cold beer, and stories from the trail.', ARRAY['https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=1000&q=85'], false, false, '(715) 555-0109', NULL, '5143 Highway B, Land O’ Lakes, WI')
('eat-07', 'hodag-coffee-house', 'Hodag Coffee House', 'eat-drink', 'coffee', 'rhinelander', '$', ARRAY['Breakfast', 'Wi-Fi', 'Pastries'], 'A downtown cup of coffee, a breakfast sandwich, and a good place to plan the day.', ARRAY['https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1000&q=85'], false, false, '(715) 555-0181', NULL, '18 Davenport Street, Rhinelander, WI')
('eat-08', 'flambeau-table', 'Flambeau Table', 'eat-drink', 'restaurant', 'mercer', '$$', ARRAY['Seasonal', 'Local Produce', 'Patio'], 'Seasonal Northwoods cooking with a menu that follows the woods and water around Mercer.', ARRAY['https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1000&q=85'], false, true, '(715) 555-0177', NULL, '102 Railroad Street, Mercer, WI')
('eat-09', 'ironwood-ale-house', 'Ironwood Ale House', 'eat-drink', 'brewery', 'hurley-ironwood', '$$', ARRAY['Craft Beer', 'Pizza', 'Live Music'], 'A border-town taproom with wood-fired pizza, local pours, and a lively weekend calendar.', ARRAY['https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=1000&q=85'], false, false, '(715) 555-0199', NULL, '214 Silver Street, Hurley, WI')
('eat-10', 'toad-in-the-hole', 'The Toad in the Hole', 'eat-drink', 'bar', 'presque-isle', '$$', ARRAY['Pub Fare', 'Games', 'Fireplace'], 'A cozy pub with a fireplace, easy conversation, and the right kind of after-lake appetite.', ARRAY['https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=1000&q=85'], false, false, '(715) 555-0139', NULL, '9 Old County Road, Presque Isle, WI')
('do-01', 'hodag-outfitters', 'Hodag Outfitters', 'things-to-do', 'boating', 'rhinelander', '$$', ARRAY['Kayaks', 'Guides', 'Lake Tours'], 'Friendly guides and gear for getting out on the water around Rhinelander.', ARRAY['https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1502680390469-be75c86b636f?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1000&q=85'], true, false, '(715) 555-0161', 'https://example.com', '44 Oneida Street, Rhinelander, WI')
('do-02', 'northwoods-musky-guide', 'Northwoods Musky Guide Service', 'things-to-do', 'fishing', 'boulder-junction', '$$$', ARRAY['Musky', 'Half Day', 'All Gear'], 'Chase a legendary fish with a patient local guide who knows the clear-water lakes by heart.', ARRAY['https://images.unsplash.com/photo-1534943441045-1009d7cbf97c?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1502680390469-be75c86b636f?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1000&q=85'], true, false, '(715) 555-0187', NULL, 'Boulder Junction Marina, Boulder Junction, WI')
('do-03', 'heart-of-the-forest-trails', 'Heart of the Forest Trails', 'things-to-do', 'hiking', 'boulder-junction', '$', ARRAY['Biking', 'Hiking', 'Scenic'], 'Miles of rolling forest trail for a morning ride, a family walk, or a full day outside.', ARRAY['https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1497250681960-ef046c08a56e?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=1000&q=85'], false, true, '(715) 555-0193', NULL, 'Trailhead Road, Boulder Junction, WI')
('do-04', 'eagle-river-snowmobile-rentals', 'Eagle River Snowmobile Rentals', 'things-to-do', 'snowmobiling', 'eagle-river', '$$', ARRAY['Trails', 'Rentals', 'Helmets Included'], 'Grab a sled and head for the famous Eagle River trail system with local route advice.', ARRAY['https://images.unsplash.com/photo-1517825738774-7de9363ef735?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1000&q=85'], false, true, '(715) 555-0145', NULL, '202 Trailside Drive, Eagle River, WI')
('do-05', 'presque-isle-dark-sky', 'Presque Isle Dark Sky Tours', 'things-to-do', 'hiking', 'presque-isle', '$$', ARRAY['Stargazing', 'Guided', 'Night Sky'], 'Learn the constellations and the stories above them under one of Wisconsin’s darkest skies.', ARRAY['https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1531497865144-0464ef8fb9a9?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1000&q=85'], false, false, '(715) 555-0172', NULL, 'Dark Sky Park Road, Presque Isle, WI')
